// ============================================
// VALIDATION INPUT
// ============================================

const input = $input.first().json;
const body = input.body || {};
const headers = input.headers || {};

// --- Extraction Project ID ---
const projectId = headers['x-project-id'] 
  || headers['X-Project-ID'] 
  || headers['X-Project-Id']
  || 'unknown';

// --- Validation discord_user_id ---
if (!body.discord_user_id) {
  return {
    error: true,
    error_code: 'MISSING_USER_ID',
    message: 'Le champ "discord_user_id" est requis'
  };
}

// --- Validation coupon_code ---
if (!body.coupon_code || typeof body.coupon_code !== 'string') {
  return {
    error: true,
    error_code: 'MISSING_COUPON_CODE',
    message: 'Le champ "coupon_code" est requis'
  };
}

// --- Retour des donnees validees ---
return {
  error: false,
  data: {
    discord_user_id: body.discord_user_id,
    coupon_code: body.coupon_code.trim().toUpperCase(),
    project_id: projectId
  }
};

// ============================================
// FORMAT SUCCESS RESPONSE
// ============================================

const apiResponse = $input.first().json;
const validationData = $('Validate Input').first().json;

// --- Check API errors ---
if (apiResponse.error || apiResponse.success === false) {
  return {
    success: false,
    error: {
      code: apiResponse.error?.code || 'COUPON_ERROR',
      message: apiResponse.error?.message || 'Erreur application coupon',
      http_status: apiResponse.error?.http_status || 400
    }
  };
}

// --- Format cart totals ---
const cart = apiResponse.cart || apiResponse;
const totalEuros = (cart.total_cents || 0) / 100;
const totalDisplay = totalEuros.toLocaleString('fr-FR', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
}) + ' EUR';

const discountEuros = (cart.discount_cents || 0) / 100;
const discountDisplay = discountEuros.toLocaleString('fr-FR', {
  minimumFractionDigits: 2,
  maximumFractionDigits: 2
}) + ' EUR';

// --- Success response ---
return {
  success: true,
  coupon: {
    code: validationData.data.coupon_code,
    discount_cents: cart.discount_cents || 0,
    discount_display: discountDisplay,
    type: cart.coupon?.type || 'percent'
  },
  cart: {
    subtotal_cents: cart.subtotal_cents || 0,
    discount_cents: cart.discount_cents || 0,
    total_cents: cart.total_cents || 0,
    total_display: totalDisplay
  }
};

// ============================================
// FORMAT ERROR RESPONSE (Validation)
// ============================================

const input = $input.first().json;

return {
  success: false,
  error: {
    code: input.error_code || 'VALIDATION_ERROR',
    message: input.message || 'Erreur de validation',
    http_status: 400
  }
};

